import unittest

from solution import expand_layouts


class ExpandLayoutsTests(unittest.TestCase):
    def test_scaling_order_labels_and_deep_copy(self):
        shared_metadata = {"tags": ["indoor"], "nested": {"level": 2}}
        layouts = {
            "zeta": {
                "scale": 2,
                "box": [1, 2.5, 3],
                "points": [
                    {"kind": "door", "position": [1, 0, 2]},
                    {"kind": "desk", "position": [0.5, 1, 1.5]},
                ],
                "metadata": shared_metadata,
            },
            "alpha": {
                "scale": 0.5,
                "box": (4, 6, 8),
                "points": [{"kind": "door", "position": (2, 4, 6)}],
                "metadata": shared_metadata,
            },
        }
        kind_map = {"door": "Entrance", "desk": "Workstation"}
        result = expand_layouts(layouts, kind_map)
        self.assertEqual([item["name"] for item in result], ["alpha", "zeta"])
        self.assertEqual(result[0]["box"], [2.0, 3.0, 4.0])
        self.assertEqual(result[0]["labels"], ["Entrance"])
        self.assertEqual(result[0]["positions"], [[1.0, 2.0, 3.0]])
        self.assertEqual(result[1]["box"], [2, 5.0, 6])
        self.assertEqual(result[1]["labels"], ["Entrance", "Workstation"])
        self.assertEqual(result[1]["positions"], [[2, 0, 4], [1.0, 2, 3.0]])

        shared_metadata["tags"].append("changed")
        layouts["zeta"]["box"][0] = 99
        kind_map["door"] = "Changed"
        self.assertEqual(result[0]["metadata"]["tags"], ["indoor"])
        self.assertEqual(result[1]["metadata"]["tags"], ["indoor"])
        self.assertEqual(result[1]["box"][0], 2)
        self.assertEqual(result[0]["labels"], ["Entrance"])

        result[0]["metadata"]["tags"].append("only-alpha")
        result[0]["positions"][0][0] = 999
        self.assertEqual(result[1]["metadata"]["tags"], ["indoor"])
        self.assertEqual(result[1]["positions"][0], [2, 0, 4])

    def test_empty_and_optional_metadata(self):
        self.assertEqual(expand_layouts({}, {}), [])
        result = expand_layouts(
            {"plain": {"scale": 1, "box": [1, 1, 1], "points": []}},
            {},
        )
        self.assertEqual(result, [{
            "name": "plain", "box": [1, 1, 1], "labels": [],
            "positions": [], "metadata": {},
        }])

    def test_malformed_data(self):
        valid = {"x": {"scale": 1, "box": [1, 2, 3], "points": []}}
        cases = [
            ([], {}),
            ({"x": []}, {}),
            ({"x": {"scale": 0, "box": [1, 2, 3], "points": []}}, {}),
            ({"x": {"scale": True, "box": [1, 2, 3], "points": []}}, {}),
            ({"x": {"scale": 1, "box": [1, 2], "points": []}}, {}),
            ({"x": {"scale": 1, "box": [1, -2, 3], "points": []}}, {}),
            ({"x": {"scale": 1, "box": [1, 2, 3], "points": [{}]}}, {}),
            ({"x": {"scale": 1, "box": [1, 2, 3], "points": [
                {"kind": "door", "position": [1, 2, 3]}
            ]}}, {}),
            ({"x": {"scale": 1, "box": [1, 2, 3], "points": [
                {"kind": "door", "position": [1, 2]}
            ]}}, {"door": "D"}),
            (valid, []),
        ]
        for layouts, kind_map in cases:
            with self.subTest(layouts=layouts, kind_map=kind_map):
                with self.assertRaises(ValueError):
                    expand_layouts(layouts, kind_map)


if __name__ == "__main__":
    unittest.main()

